function gcContent(seq){ seq=String(seq).toUpperCase().replace(/U/g,'T').replace(/[^ACGT]/g,''); if(!seq.length) return 0; var gc=0; for(var i=0;i<seq.length;i++){ var c=seq[i]; if(c==='G'||c==='C') gc++; } return gc/seq.length; }
function tmWallace(seq){ seq=String(seq).toUpperCase().replace(/U/g,'T').replace(/[^ACGT]/g,''); var a=0,t=0,g=0,c=0; for(var i=0;i<seq.length;i++){ var x=seq[i]; if(x==='A')a++; else if(x==='T')t++; else if(x==='G')g++; else if(x==='C')c++; } return 2*(a+t)+4*(g+c); }
function tmBasic(seq){ seq=String(seq).toUpperCase().replace(/U/g,'T').replace(/[^ACGT]/g,''); var n=seq.length; if(n===0) return NaN; var gc=gcContent(seq); return 81.5 + 0.41*(gc*100) - 675/n; }
function annealingTemp(seq){ return tmBasic(seq) - 5; }
function dilute(c1, v1, c2){ if(!c2) return NaN; return c1*v1/c2; }
var EXPORTS={ gcContent:gcContent, tmWallace:tmWallace, tmBasic:tmBasic, annealingTemp:annealingTemp, dilute:dilute };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PcrForgePure = EXPORTS; }
